#include <cstdio>
#include <cstdlib>
#include <vector>

static std::vector<int> bigadd(const std::vector<int>& x, const std::vector<int>& y) {
    std::vector<int> r;
    int carry = 0;
    size_t m = x.size() > y.size() ? x.size() : y.size();
    for (size_t i = 0; i < m; i++) {
        int s = carry;
        if (i < x.size()) s += x[i];
        if (i < y.size()) s += y[i];
        r.push_back(s % 10);
        carry = s / 10;
    }
    while (carry > 0) { r.push_back(carry % 10); carry = carry / 10; }
    return r;
}

int main(int argc, char** argv) {
    long long n = 0;
    if (argc > 1) n = atoll(argv[1]);
    if (n < 0) n = 0;
    std::vector<int> a; a.push_back(1);
    std::vector<int> b; b.push_back(1);
    for (long long i = 0; i < n; i++) {
        std::vector<int> c = bigadd(a, b);
        a = b;
        b = c;
    }
    for (size_t i = a.size(); i > 0; i--) putchar('0' + a[i - 1]);
    putchar('\n');
    return 0;
}
